# Function to find the sum of distinct prime divisors of a given number
def sum_distinct_prime_divisors(n):
    # Function to check if a number is prime
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True
    
    # Factorize the number and collect distinct prime factors
    prime_factors = set()
    num = n
    for i in range(2, int(num**0.5) + 1):
        while num % i == 0:
            prime_factors.add(i)
            num //= i
    
    if num > 1:
        prime_factors.add(num)
    
    # Sum the distinct prime factors
    return sum(prime_factors)

# Given number
