    def divisors_sum(n):
        result = 1
        for p in get_prime_factors(n):
            exponent = 0
            while n % p == 0:
                n //= p
                exponent += 1
            result *= (1 + p + p**exponent)
        return result

    def get_prime_factors(n):
        factors = set()
        for i in range(2, int(n**0.5) + 1):
            while n % i == 0:
                factors.add(i)
                n //= i
        if n > 1:
            factors.add(n)
        return factors

    return divisors_sum(number)

